import re

def run(spec: str, verilog: str, ports: list[dict]) -> dict:
    """
    Detects designs that have a reset-like input (reset, resetn, aresetn, rst_n, etc.)
    but do NOT include that signal in the sensitivity list of any always_ff or
    always @(posedge clk) block.
    Returns {"fired": bool, "findings": [str]}.
    """
    # Find all reset-like signal names (case-insensitive)
    reset_pattern = re.compile(r'\b(reset|resetn|aresetn|rst_n?)\b', re.IGNORECASE)
    reset_signals = set(m.group(0).lower() for m in reset_pattern.finditer(verilog))

    if not reset_signals:
        return {"fired": False, "findings": []}

    # Find always blocks that are edge-sensitive (posedge clk) and capture their sensitivity list
    # Simple regex: always @( ... ) or always @(posedge clk ... )
    always_pattern = re.compile(
        r'always\s*@\s*\(([^)]*)\)\s*', re.IGNORECASE | re.DOTALL
    )
    missing = []
    for sens in always_pattern.findall(verilog):
        # Normalize sensitivity list: split by commas, ignore whitespace, comments
        sens_clean = re.sub(r'//.*', '', sens)
        sens_clean = re.sub(r'/\\*.*?\\*/', '', sens_clean, flags=re.DOTALL)
        tokens = [tok.strip().lower() for tok in sens_clean.split(',') if tok.strip()]
        # Check if any reset signal appears in this sensitivity list
        if not any(reset in tokens for reset in reset_signals):
            missing.append(sens.strip())

    if missing:
        findings = [
            f"Reset signal(s) {', '.join(sorted(reset_signals))} missing from sensitivity list in always block(s): {', '.join(missing)}"
        ]
        return {"fired": True, "findings": findings}
    else:
        return {"fired": False, "findings": []}
}
